# Path: reinvent/chemistry/conversions.py
class Conversions:
    @staticmethod
    def smiles_to_mols_and_indices(query_smiles: List[str]) -> Tuple[List[Mol], List[int]]:
        mols = [MolFromSmiles(smile) for smile in query_smiles]
        valid_mask = [mol is not None for mol in mols]
        valid_idxs = [idx for idx, is_valid in enumerate(valid_mask) if is_valid]
        valid_mols = [mols[idx] for idx in valid_idxs]
        return valid_mols, valid_idxs

    @staticmethod
    def mols_to_fingerprints(
        molecules: List[Mol], radius: int = 3, use_counts: bool = True, use_features: bool = True
    ) -> List[UIntSparseIntVect]:
        fingerprints = [
            AllChem.GetMorganFingerprint(
                mol, radius, useCounts=use_counts, useFeatures=use_features
            )
            for mol in molecules
        ]
        return fingerprints

    @staticmethod
    def smiles_to_mols(query_smiles: List[str]) -> List[Mol]:
        mols = [MolFromSmiles(smile) for smile in query_smiles]
        valid_mask = [mol is not None for mol in mols]
        valid_idxs = [idx for idx, is_valid in enumerate(valid_mask) if is_valid]
        valid_mols = [mols[idx] for idx in valid_idxs]
        return valid_mols

    def smiles_to_fingerprints(
        self, query_smiles: List[str], radius=3, use_counts=True, use_features=True
    ) -> List[UIntSparseIntVect]:
        mols = self.smiles_to_mols(query_smiles)
        fingerprints = self.mols_to_fingerprints(
            mols, radius=radius, use_counts=use_counts, use_features=use_features
        )
        return fingerprints

    def smile_to_mol(self, smile: str) -> Mol:
        """
        Creates a Mol object from a SMILES string.
        :param smile: SMILES string.
        :return: A Mol object or None if it's not valid.
        """
        if smile:
            return MolFromSmiles(smile)

    def mols_to_smiles(
        self, molecules: List[Mol], isomericSmiles=False, canonical=True
    ) -> List[str]:
        """This method assumes that all molecules are valid."""
        valid_smiles = [
            MolToSmiles(mol, isomericSmiles=isomericSmiles, canonical=canonical)
            for mol in molecules
        ]
        return valid_smiles

    def mol_to_smiles(self, molecule: Mol, isomericSmiles=False, canonical=True) -> str:
        """
        Converts a Mol object into a canonical SMILES string.
        :param molecule: Mol object.
        :return: A SMILES string.
        """
        if molecule:
            return MolToSmiles(molecule, isomericSmiles=isomericSmiles, canonical=canonical)

    def mol_to_random_smiles(self, molecule: Mol) -> str:
        """
        Converts a Mol object into a random SMILES string.
        :return: A SMILES string.
        """
        if molecule:
            new_atom_order = list(range(molecule.GetNumAtoms()))
            random.shuffle(new_atom_order)
            random_mol = RenumberAtoms(molecule, newOrder=new_atom_order)
            return MolToSmiles(random_mol, canonical=False, isomericSmiles=False)

    def convert_to_rdkit_smiles(
        self, smiles: str, allowTautomers=True, sanitize=False, isomericSmiles=False
    ) -> str:
        """
        :param smiles: Converts a smiles string into a canonical SMILES string.
        :type allowTautomers: allows having same molecule represented in different tautomeric forms
        """
        if allowTautomers:
            return MolToSmiles(
                MolFromSmiles(smiles, sanitize=sanitize), isomericSmiles=isomericSmiles
            )
        else:
            return MolStandardize.canonicalize_tautomer_smiles(smiles)

    def convert_to_standardized_smiles(self, smiles: str) -> Optional[str]:
        """Standardize SMILES for Mol2Mol

        This should only be used to validate and transform user input
        because the code will abort execution on any error it finds.

        param smiles: single SMILES string
        return: single SMILES string
        """

        mol = MolFromSmiles(smiles, sanitize=True)

        if not mol:  # RDKit fails silently
            raise RuntimeError(f"RDKit does not accept SMILES: {smiles}")

        standardizer = Standardizer()  # MolVS

        try:
            smol = standardizer(mol)  # runs SanitizeMol() first
            smol = standardizer.charge_parent(smol)  # largest fragment uncharged
            smi = MolToSmiles(smol, isomericSmiles=True)
        except Exception as error:  # RDKit may raise multiple exceptions
            raise RuntimeError(f"RDKit does not accept SMILES: {smiles} {error}")

        # Sometimes when standardizing ChEMBL [H] are not removed so try a
        # second call
        if "[H]" in smi:
            return self.convert_to_standardized_smiles(smi)
        else:
            return smi

    def copy_mol(self, molecule: Mol) -> Mol:
        """
        Copies, sanitizes, canonicalizes and cleans a molecule.
        :param molecule: A Mol object to copy.
        :return : Another Mol object copied, sanitized, canonicalized and cleaned.
        """
        return self.smile_to_mol(self.mol_to_smiles(molecule))

    def randomize_smiles(self, smiles: str) -> str:
        """
        Returns a random SMILES given a SMILES of a molecule.
        :param smiles: A smiles string
        :returns: A random SMILES string of the same molecule or None if the molecule is invalid.
        """
        mol = MolFromSmiles(smiles)
        if mol:
            new_atom_order = list(range(mol.GetNumHeavyAtoms()))
            random.shuffle(new_atom_order)
            random_mol = RenumberAtoms(mol, newOrder=new_atom_order)
            return MolToSmiles(random_mol, canonical=False, isomericSmiles=False)

    def mol_to_inchi_key(self, molecule: Mol) -> str:
        """Returns the standard InChI key for a molecule"""
        if molecule:
            inchi_key = MolToInchiKey(molecule)
            return inchi_key

    def mol_to_sdf(self, molecules: List, input_sdf_path: str):
        """Write a set of molecules to sdf file"""
        writer = SDWriter(input_sdf_path)
        for mol in molecules:
            writer.write(mol)

# Path: reinvent/chemistry/library_design/attachment_points.py
class AttachmentPoints:
    def __init__(self):
        self._conversions = Conversions()
        self._tokens = TransformationTokens()

    def add_attachment_point_numbers(self, mol_or_smi, canonicalize=True):
        """
        Adds the numbers for the attachment points throughout the molecule.
        :param mol_or_smi: SMILES string to convert.
        :param canonicalize: Canonicalize the SMILES so that the attachment points are always in the same order.
        :return : A converted SMILES string.
        """
        if isinstance(mol_or_smi, str):
            smi = mol_or_smi
            if canonicalize:
                smi = self._conversions.mol_to_smiles(self._conversions.smile_to_mol(mol_or_smi))
            # only add numbers ordered by the SMILES ordering
            num = -1

            def _ap_callback(_):
                nonlocal num
                num += 1
                return "[{}:{}]".format(self._tokens.ATTACHMENT_POINT_TOKEN, num)

            return re.sub(self._tokens.ATTACHMENT_POINT_REGEXP, _ap_callback, smi)
        else:
            mol = mol_or_smi
            if canonicalize:
                mol = self._conversions.smile_to_mol(self._conversions.mol_to_smiles(mol))
            idx = 0
            for atom in mol.GetAtoms():
                if atom.GetSymbol() == self._tokens.ATTACHMENT_POINT_TOKEN:
                    atom.SetProp("molAtomMapNumber", str(idx))
                    idx += 1
            return self._conversions.mol_to_smiles(mol)

    def get_attachment_points(self, smile: str) -> List:
        """
        Gets all attachment points from SMILES string.
        :param smile: A SMILES string
        :return : A list with the numbers ordered by appearance.
        """
        return [
            int(match.group(1))
            for match in re.finditer(self._tokens.ATTACHMENT_POINT_NUM_REGEXP, smile)
        ]

    def get_attachment_points_for_molecule(self, molecule: Mol) -> List:
        """
        Gets all attachment points from RDKit Mol.
        :param molecule: A Mol object.
        :return : A list with the numbers ordered by appearance.
        """
        if isinstance(molecule, Mol):
            return [
                int(atom.GetProp("molAtomMapNumber"))
                for atom in molecule.GetAtoms()
                if atom.GetSymbol() == self._tokens.ATTACHMENT_POINT_TOKEN
                and atom.HasProp("molAtomMapNumber")
            ]

    def add_first_attachment_point_number(self, smi, num):
        """
        Changes/adds a number to the first attachment point.
        :param smi: SMILES string with the molecule.
        :param num: Number to add.
        :return: A SMILES string with the number added.
        """
        return re.sub(
            self._tokens.ATTACHMENT_POINT_REGEXP,
            "[{}:{}]".format(self._tokens.ATTACHMENT_POINT_TOKEN, num),
            smi,
            count=1,
        )

    def remove_attachment_point_numbers(self, smile: str) -> str:
        """
        Removes the numbers for the attachment points throughout the molecule.
        :param smile: SMILES string.
        :return : A converted SMILES string.
        """
        result = re.sub(
            self._tokens.ATTACHMENT_POINT_NUM_REGEXP,
            "[{}]".format(self._tokens.ATTACHMENT_POINT_TOKEN),
            smile,
        )
        return result

    def remove_attachment_point_numbers_from_mol(self, molecule: Mol) -> Mol:
        """
        Removes the numbers for the attachment points throughout the molecule.
        :param molecule: RDKit molecule.
        :return : A molecule.
        """
        if isinstance(molecule, Mol):
            for atom in molecule.GetAtoms():
                atom.ClearProp("molAtomMapNumber")
        return molecule

    def add_brackets_to_attachment_points(self, scaffold: str):
        """
        Adds brackets to the attachment points (if they don't have them).
        :param scaffold: SMILES string.
        :return: A SMILES string with attachments in brackets.
        """
        return re.sub(
            self._tokens.ATTACHMENT_POINT_NO_BRACKETS_REGEXP,
            "[{}]".format(self._tokens.ATTACHMENT_POINT_TOKEN),
            scaffold,
        )

# Path: reinvent/chemistry/library_design/bond_maker.py
class BondMaker:
    def __init__(self):
        self._conversions = Conversions()
        self._tokens = TransformationTokens()
        self._attachment_points = AttachmentPoints()

    def join_scaffolds_and_decorations(
        self, scaffold_smi: str, decorations_smi, keep_labels_on_atoms=False
    ) -> Optional[Mol]:
        decorations_smi = [
            self._attachment_points.add_first_attachment_point_number(dec, i)
            for i, dec in enumerate(decorations_smi.split(self._tokens.ATTACHMENT_SEPARATOR_TOKEN))
        ]
        num_attachment_points = len(self._attachment_points.get_attachment_points(scaffold_smi))
        if len(decorations_smi) != num_attachment_points:
            return None

        mol = self._conversions.smile_to_mol(scaffold_smi)
        for decoration in decorations_smi:
            mol = self.join_molecule_fragments(
                mol,
                self._conversions.smile_to_mol(decoration),
                keep_label_on_atoms=keep_labels_on_atoms,
            )
            if not mol:
                return None
        return mol

    def join_molecule_fragments(self, scaffold: Mol, decoration: Mol, keep_label_on_atoms=False):
        """
        Joins a RDKit MOL scaffold with a decoration. They must be labelled.
        :param scaffold: RDKit MOL of the scaffold.
        :param decoration: RDKit MOL of the decoration.
        :param keep_label_on_atoms: Add the labels to the atoms after attaching the molecule.
        This is useful when debugging, but it can give problems.
        :return: A Mol object of the joined scaffold.
        """

        if scaffold and decoration:
            # obtain id in the decoration
            try:
                attachment_points = [
                    atom.GetProp("molAtomMapNumber")
                    for atom in decoration.GetAtoms()
                    if atom.GetSymbol() == self._tokens.ATTACHMENT_POINT_TOKEN
                ]
                if len(attachment_points) != 1:
                    return None  # more than one attachment point...
                attachment_point = attachment_points[0]
            except KeyError:
                return None

            combined_scaffold = RWMol(CombineMols(decoration, scaffold))
            attachments = [
                atom
                for atom in combined_scaffold.GetAtoms()
                if atom.GetSymbol() == self._tokens.ATTACHMENT_POINT_TOKEN
                and atom.HasProp("molAtomMapNumber")
                and atom.GetProp("molAtomMapNumber") == attachment_point
            ]
            if len(attachments) != 2:
                return None  # something weird

            neighbors = []
            for atom in attachments:
                if atom.GetDegree() != 1:
                    return None  # the attachment is wrongly generated
                neighbors.append(atom.GetNeighbors()[0])

            bonds = [atom.GetBonds()[0] for atom in attachments]
            bond_type = BondType.SINGLE
            if any(bond for bond in bonds if bond.GetBondType() == BondType.DOUBLE):
                bond_type = BondType.DOUBLE

            combined_scaffold.AddBond(neighbors[0].GetIdx(), neighbors[1].GetIdx(), bond_type)
            combined_scaffold.RemoveAtom(attachments[0].GetIdx())
            combined_scaffold.RemoveAtom(attachments[1].GetIdx())

            if keep_label_on_atoms:
                for neigh in neighbors:
                    self._add_attachment_point_num(neigh, attachment_point)

            # Label the atoms in the bond
            bondNumbers = [
                int(atom.GetProp("bondNum"))
                for atom in combined_scaffold.GetAtoms()
                if atom.HasProp("bondNum")
            ]

            if bondNumbers:
                bondNum = max(bondNumbers) + 1
            else:
                bondNum = 0

            for neighbor in neighbors:
                idx = neighbor.GetIdx()
                atom = combined_scaffold.GetAtomWithIdx(idx)
                atom.SetIntProp("bondNum", bondNum)
            ##########################################

            scaffold = combined_scaffold.GetMol()
            try:
                SanitizeMol(scaffold)
            except ValueError:  # sanitization error
                return None
        else:
            return None

        return scaffold

    def _add_attachment_point_num(self, atom, idx):
        idxs = []
        if atom.HasProp("molAtomMapNumber"):
            idxs = atom.GetProp("molAtomMapNumber").split(",")
        idxs.append(str(idx))
        idxs = sorted(list(set(idxs)))
        atom.SetProp("molAtomMapNumber", ",".join(idxs))
        # Fixme: This way of annotating fails in case of several attachment points when the mol is converted back to a
        #  SMILES string (RuntimeError: boost::bad_any_cast: failed conversion using boost::any_cast)
        #  For example combining scaffold '*C(*)CC' and  warhead pair '*OC|*C' would result in
        #  C[O:0][CH:0,1]([CH3:1])CC, which results in an error due to the '0,1'

    def randomize_scaffold(self, scaffold: Mol):
        smi = self._conversions.mol_to_random_smiles(scaffold)
        conv_smi = None
        if smi:
            conv_smi = self._attachment_points.add_brackets_to_attachment_points(smi)
        return conv_smi

# Path: reinvent/chemistry/library_design/fragment_reactions.py
class FragmentReactions:
    def __init__(self):
        self._conversions = Conversions()
        self._tokens = TransformationTokens()
        self._bond_mapper = BondMapper()

    def create_reactions_from_smarts(self, smarts: List[str]) -> List[ChemicalReaction]:
        reactions = [AllChem.ReactionFromSmarts(smirks) for smirks in smarts]
        return reactions

    def create_reaction_from_smirk(self, smirks: str) -> ReactionDTO:
        reaction = ReactionDTO(smirks, AllChem.ReactionFromSmarts(smirks))
        return reaction

    def create_reactions_from_smirks(self, smirks: List[str]) -> List[ReactionDTO]:
        reactions = [self.create_reaction_from_smirk(smirk) for smirk in smirks]
        return reactions

    def slice_molecule_to_fragments(
        self, molecule: Mol, reaction_dtos: List[ReactionDTO]
    ) -> List[Tuple[Mol]]:
        """
        This method applies a list of chemical reactions on a molecule and
        decomposes the input molecule to complementary fragments.
        :param molecule:
        :param reaction_dtos:
        :return: Different slicing combinations are returned.
        """
        list_of_outcomes = self.apply_reactions_on_molecule(molecule, reaction_dtos)
        all_outcomes = []

        for outcome in list_of_outcomes:
            all_outcomes.extend(outcome.reaction_outcomes)
        # TODO: the overall data processing is extremely slow. consider reducing redundancy here.
        return all_outcomes

    def apply_reactions_on_molecule(
        self, molecule: Mol, reaction_dtos: List[ReactionDTO]
    ) -> List[ReactionOutcomeDTO]:
        """Build list of possible splits of a molecule given multiple reactions."""
        list_of_outcomes = []
        for reaction_dto in reaction_dtos:
            outcome_dto = self.apply_reaction_on_molecule(molecule, reaction_dto)
            purged_outcome_dto = self._filter_pairs_with_no_ring_count_change(outcome_dto)
            list_of_outcomes.append(purged_outcome_dto)
        return list_of_outcomes

    def apply_reaction_on_molecule(
        self, molecule: Mol, reaction_dto: ReactionDTO
    ) -> ReactionOutcomeDTO:
        """Build list of possible splits of a molecule given a single reaction."""
        molecule = self._conversions.copy_mol(molecule)
        outcomes = reaction_dto.chemical_reaction.RunReactant(molecule, 0)
        outcome_dto = ReactionOutcomeDTO(reaction_dto.reaction_smarts, list(outcomes), molecule)
        return outcome_dto

    def _filter_pairs_with_no_ring_count_change(
        self, outcome_dto: ReactionOutcomeDTO
    ) -> ReactionOutcomeDTO:
        molecule_rings = RingCount(outcome_dto.targeted_molecule)
        acceptable_pairs = []
        for pair in outcome_dto.reaction_outcomes:
            if not self._detect_ring_break(molecule_rings, pair) and len(pair) == 2:
                acceptable_pairs.append(pair)
        outcome_dto.reaction_outcomes = acceptable_pairs
        return outcome_dto

    def _detect_ring_break(self, molecule_ring_count: int, pair: Tuple[Mol]) -> bool:
        reagent_rings = 0
        for reagent in pair:
            reagent_smiles = self._conversions.mol_to_smiles(reagent)
            reagent_mol = self._conversions.smile_to_mol(reagent_smiles)
            try:
                reagent_rings = reagent_rings + RingCount(reagent_mol)
            except:
                return True
        return molecule_ring_count != reagent_rings

