        for cmd in if_cm.body:
            cmd.accept(self)

        for cmd in if_cm.body:
            cmd.accept(self)

        self.if_else_depth -= 1

    def visit_parallel(self, parallel_cm):
        for cmd in parallel_cm.body:
            cmd.accept(self)

    def visit_for_range(self, for_range_cm):
        for cmd in for_range_cm.body:
            cmd.accept(self)

